// Verifies the HMAC signature sent by Future Creative (X-FC-Signature) and rejects replays older than 5 minutes.
const crypto = require('crypto');
const secret = $env.FC_WEBHOOK_SECRET;
if (!secret) throw new Error('FC_WEBHOOK_SECRET is not set in the n8n environment');
const out = [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  const ts = h['x-fc-timestamp'];
  const sig = h['x-fc-signature'] || '';
  const body = JSON.stringify(item.json.body);
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
  const ok = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
  if (!ok) throw new Error('Invalid signature — event rejected');
  if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('Stale event (replay protection)');
  out.push({ json: { ...item.json.body, deliveryId: h['x-fc-delivery'] } });
}
return out;

// Builds an Arabic Telegram message (and photo + approve/reject buttons for new designs).
const e = $input.first().json;
const d = e.data || {};
const base = e.dashboard || '';
const link = (p) => (p ? base + p : base);
let text = `🔔 ${e.title}
`;
let photo = null, buttons = null;
switch (e.event) {
  case 'ad.ready_for_review':
    text += `الحساب: ${d.account?.name ?? ''}
الصيغة: ${d.format}
العنوان: ${d.headline ?? ''}
${d.dryRun ? '⚠️ معاينة تجريبية — غير قابلة للنشر
' : ''}${d.qcPassed ? '✅ اجتاز فحص الجودة' : '❌ لم يجتز فحص الجودة'}

${(d.caption || '').slice(0, 600)}

مراجعة: ${link(d.reviewUrl)}`;
    photo = d.imageUrl ? (d.imageUrl.startsWith('http') ? d.imageUrl : base + d.imageUrl) : null;
    if (d.qcPassed && !d.dryRun) buttons = { inline_keyboard: [[{ text: '✅ اعتماد', callback_data: `a:${d.adId}` }, { text: '❌ رفض', callback_data: `r:${d.adId}` }]] };
    break;
  case 'publication.published': text += `الحساب: ${d.account}
${d.publicUrl ? 'الرابط: ' + d.publicUrl : ''}`; break;
  case 'publication.scheduled': text += `الحساب: ${d.account}
موعد النشر: ${d.publishAt}`; break;
  case 'publication.failed': text += `الحساب: ${d.account ?? d.accountId}
السبب: ${d.reason}
سجل المنشورات: ${link('/posts?state=FAILED')}`; break;
  case 'publication.unknown': text += `الحساب: ${d.account}
${d.error}
تحقق في Metricool ثم قرر من: ${link('/posts?state=UNKNOWN')}`; break;
  case 'connection.lost': text += `الحساب: ${d.account}
${d.reason}
أعد الربط ثم «فحص كل الحسابات الآن».`; break;
  case 'report.weekly': {
    const m = d.metrics || {};
    text += `منشورات مؤكدة: ${m.posts ?? 0} · بمقاييس: ${m.withMetrics ?? 0}
الوصول: ${m.reach ?? 0} · المشاهدات: ${m.views ?? 0}
الحفظ+المشاركة: ${(m.saves ?? 0) + (m.shares ?? 0)} · متوسط التفاعل: ${m.avgEngagement ?? '—'}%
${m.reelSkipRatePct != null ? `تخطي الريلز: ${m.reelSkipRatePct}%
` : ''}
التوصيات:
• ${(d.recommendations || []).slice(0, 5).join('
• ')}

${link('/reports')}`;
    break;
  }
  default: text += JSON.stringify(d).slice(0, 800);
}
return [{ json: { text: text.slice(0, photo ? 1000 : 4000), photo, buttons } }];

// Sends to Telegram through the Bot API (token and chat come from the n8n environment).
const { text, photo, buttons } = $input.first().json;
const token = $env.TELEGRAM_BOT_TOKEN, chat = $env.TELEGRAM_CHAT_ID;
if (!token || !chat) throw new Error('Set TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID in .env');
const method = photo ? 'sendPhoto' : 'sendMessage';
const body = photo ? { chat_id: chat, photo, caption: text, reply_markup: buttons || undefined } : { chat_id: chat, text, reply_markup: buttons || undefined, disable_web_page_preview: true };
const res = await this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${token}/${method}`, body, json: true });
return [{ json: { ok: res.ok, method } }];
